using HealthReadinessLab;
using Xunit;
public sealed class HealthTests { [Fact] public async Task Startup_is_unhealthy_until_initialized() { var s = new StartupState(); var p = new StartupProbe(s); Assert.Equal(HealthStatus.Unhealthy, (await p.CheckAsync(default)).Status); s.Ready = true; Assert.Equal(HealthStatus.Healthy, (await p.CheckAsync(default)).Status); } [Fact] public async Task Failed_required_dependency_makes_readiness_unhealthy() { var r = await new HealthEvaluator([new DependencyProbe(_ => ValueTask.FromResult(false))]).CheckAsync(); Assert.Equal(HealthStatus.Unhealthy, HealthEvaluator.Aggregate(r)); } [Fact] public void Degraded_aggregates_without_unhealthy() { Assert.Equal(HealthStatus.Degraded, HealthEvaluator.Aggregate([new("x", HealthStatus.Healthy, ""), new("y", HealthStatus.Degraded, "")])); } [Fact] public async Task Cancellation_reaches_dependency() { var seen = false; using var cts = new CancellationTokenSource(); cts.Cancel(); var p = new DependencyProbe(ct => { seen = ct.IsCancellationRequested; return ValueTask.FromCanceled<bool>(ct); }); await Assert.ThrowsAnyAsync<OperationCanceledException>(async () => await p.CheckAsync(cts.Token)); Assert.True(seen); } }
